pub const ANALYZE_LOGS: &str = r#"Analyze only the supplied bounded log evidence. Do not mutate production files, tests, Git metadata, fixture state, database state, deploy state, triggers, or workers. Produce one or more falsifiable hypotheses with exact evidence ids. Write exactly one JSON object matching the supplied result contract to the file `<result_root>/analyze_logs.json`; do not create any other result file."#;

